/**
 * Path caching system with TTL (Time-To-Live) and LRU eviction
 * for CPU optimization by reducing redundant pathfinding operations.
 *
 * Key features:
 * - TTL-based expiration (default 1500 ticks ~100 game time)
 * - LRU eviction when cache exceeds size limit
 * - Cost matrix caching for terrain and structures
 * - Cache metrics tracking (hit rate, CPU savings)
 */

/**
 * Cached path entry with metadata
 */
export interface CachedPath {
  /** The calculated path as room positions */
  path: RoomPosition[];
  /** Tick when the path was cached */
  cachedAt: number;
  /** Number of operations used for pathfinding */
  ops: number;
  /** CPU cost of pathfinding operation */
  cpuCost: number;
  /** Whether pathfinding was incomplete */
  incomplete: boolean;
  /** Last tick this entry was accessed (for LRU) */
  lastAccessed: number;
}

/**
 * Cached cost matrix entry
 */
export interface CachedCostMatrix {
  /** The cost matrix */
  matrix: CostMatrix;
  /** Tick when the matrix was cached */
  cachedAt: number;
  /** Last tick this entry was accessed (for LRU) */
  lastAccessed: number;
}

/**
 * Cache metrics for monitoring and optimization
 */
export interface PathCacheMetrics {
  /** Total cache hits */
  hits: number;
  /** Total cache misses */
  misses: number;
  /** Cache hit rate (hits / (hits + misses)) */
  hitRate: number;
  /** Total CPU saved by cache hits */
  cpuSaved: number;
  /** Current cache size (path entries) */
  pathCacheSize: number;
  /** Current cost matrix cache size */
  costMatrixCacheSize: number;
  /** Number of entries evicted due to LRU */
  lruEvictions: number;
  /** Number of entries evicted due to TTL */
  ttlEvictions: number;
}

/**
 * Configuration for path cache
 */
export interface PathCacheConfig {
  /** TTL for cached paths in ticks (default: 1500) */
  ttl?: number;
  /** Maximum number of cached paths (default: 1000) */
  maxPathEntries?: number;
  /** Maximum number of cached cost matrices (default: 50) */
  maxCostMatrixEntries?: number;
  /** TTL for cost matrices in ticks (default: 3000) */
  costMatrixTtl?: number;
}

/**
 * Path cache system with TTL and LRU eviction
 */
export class PathCache {
  private readonly pathCache: Map<string, CachedPath> = new Map();
  private readonly costMatrixCache: Map<string, CachedCostMatrix> = new Map();

  private readonly ttl: number;
  private readonly maxPathEntries: number;
  private readonly maxCostMatrixEntries: number;
  private readonly costMatrixTtl: number;

  // Metrics
  private hits = 0;
  private misses = 0;
  private cpuSaved = 0;
  private lruEvictions = 0;
  private ttlEvictions = 0;

  public constructor(config: PathCacheConfig = {}) {
    this.ttl = config.ttl ?? 1500;
    this.maxPathEntries = config.maxPathEntries ?? 1000;
    this.maxCostMatrixEntries = config.maxCostMatrixEntries ?? 50;
    this.costMatrixTtl = config.costMatrixTtl ?? 3000;
  }

  /**
   * Generate cache key for a path
   * Format: fromX,fromY-toX,toY-roomName
   */
  public static generatePathKey(from: RoomPosition, to: RoomPosition, options?: { range?: number }): string {
    const range = options?.range ?? 1;
    return `${from.x},${from.y}-${to.x},${to.y}-${from.roomName}-${to.roomName}-r${range}`;
  }

  /**
   * Generate cache key for a cost matrix
   * Format: roomName-type
   */
  public static generateCostMatrixKey(roomName: string, type: "terrain" | "structures"): string {
    return `${roomName}-${type}`;
  }

  /**
   * Get a cached path if available and valid
   */
  public getPath(
    from: RoomPosition,
    to: RoomPosition,
    currentTick: number,
    options?: { range?: number }
  ): CachedPath | null {
    const key = PathCache.generatePathKey(from, to, options);
    const cached = this.pathCache.get(key);

    if (!cached) {
      this.misses++;
      return null;
    }

    // Check TTL
    if (currentTick - cached.cachedAt > this.ttl) {
      this.pathCache.delete(key);
      this.ttlEvictions++;
      this.misses++;
      return null;
    }

    // Update LRU timestamp
    cached.lastAccessed = currentTick;
    this.hits++;
    this.cpuSaved += cached.cpuCost;

    return cached;
  }

  /**
   * Cache a path
   */
  public setPath(
    from: RoomPosition,
    to: RoomPosition,
    path: RoomPosition[],
    currentTick: number,
    metadata: {
      ops: number;
      cpuCost: number;
      incomplete: boolean;
      range?: number;
    }
  ): void {
    // Evict old entries if cache is full
    if (this.pathCache.size >= this.maxPathEntries) {
      this.evictLRUPath(currentTick);
    }

    const key = PathCache.generatePathKey(from, to, { range: metadata.range });
    this.pathCache.set(key, {
      path,
      cachedAt: currentTick,
      ops: metadata.ops,
      cpuCost: metadata.cpuCost,
      incomplete: metadata.incomplete,
      lastAccessed: currentTick
    });
  }

  /**
   * Get a cached cost matrix if available and valid
   */
  public getCostMatrix(roomName: string, type: "terrain" | "structures", currentTick: number): CostMatrix | null {
    const key = PathCache.generateCostMatrixKey(roomName, type);
    const cached = this.costMatrixCache.get(key);

    if (!cached) {
      return null;
    }

    // Check TTL
    if (currentTick - cached.cachedAt > this.costMatrixTtl) {
      this.costMatrixCache.delete(key);
      this.ttlEvictions++;
      return null;
    }

    // Update LRU timestamp
    cached.lastAccessed = currentTick;

    return cached.matrix;
  }

  /**
   * Cache a cost matrix
   */
  public setCostMatrix(
    roomName: string,
    type: "terrain" | "structures",
    matrix: CostMatrix,
    currentTick: number
  ): void {
    // Evict old entries if cache is full
    if (this.costMatrixCache.size >= this.maxCostMatrixEntries) {
      this.evictLRUCostMatrix(currentTick);
    }

    const key = PathCache.generateCostMatrixKey(roomName, type);
    this.costMatrixCache.set(key, {
      matrix,
      cachedAt: currentTick,
      lastAccessed: currentTick
    });
  }

  /**
   * Invalidate all paths in a specific room
   */
  public invalidateRoom(roomName: string): void {
    // Use precise room name matching to avoid false positives
    // Cache key format: fromX,fromY-toX,toY-fromRoom-toRoom-rRange
    for (const [key] of this.pathCache) {
      // Parse the key to extract room names
      const parts = key.split("-");
      // Key structure: "x,y" - "x,y" - "fromRoom" - "toRoom" - "rRange"
      if (parts.length >= 5) {
        const fromRoom = parts[2];
        const toRoom = parts[3];
        if (fromRoom === roomName || toRoom === roomName) {
          this.pathCache.delete(key);
        }
      }
    }

    // Also invalidate cost matrices for the room
    const terrainKey = PathCache.generateCostMatrixKey(roomName, "terrain");
    const structuresKey = PathCache.generateCostMatrixKey(roomName, "structures");
    this.costMatrixCache.delete(terrainKey);
    this.costMatrixCache.delete(structuresKey);
  }

  /**
   * Invalidate structure-based cost matrices for a room
   * (terrain cost matrices remain valid)
   */
  public invalidateStructures(roomName: string): void {
    const structuresKey = PathCache.generateCostMatrixKey(roomName, "structures");
    this.costMatrixCache.delete(structuresKey);

    // Invalidate paths in this room (structures affect pathing)
    // Use precise room name matching to avoid false positives
    for (const [key] of this.pathCache) {
      // Parse the key to extract room names
      const parts = key.split("-");
      // Key structure: "x,y" - "x,y" - "fromRoom" - "toRoom" - "rRange"
      if (parts.length >= 5) {
        const fromRoom = parts[2];
        const toRoom = parts[3];
        if (fromRoom === roomName || toRoom === roomName) {
          this.pathCache.delete(key);
        }
      }
    }
  }

  /**
   * Clear all cached entries
   */
  public clear(): void {
    this.pathCache.clear();
    this.costMatrixCache.clear();
  }

  /**
   * Get current cache metrics
   */
  public getMetrics(): PathCacheMetrics {
    const total = this.hits + this.misses;
    const hitRate = total > 0 ? this.hits / total : 0;

    return {
      hits: this.hits,
      misses: this.misses,
      hitRate,
      cpuSaved: this.cpuSaved,
      pathCacheSize: this.pathCache.size,
      costMatrixCacheSize: this.costMatrixCache.size,
      lruEvictions: this.lruEvictions,
      ttlEvictions: this.ttlEvictions
    };
  }

  /**
   * Reset metrics (useful for per-tick or periodic reporting)
   */
  public resetMetrics(): void {
    this.hits = 0;
    this.misses = 0;
    this.cpuSaved = 0;
    this.lruEvictions = 0;
    this.ttlEvictions = 0;
  }

  /**
   * Evict the least recently used path entry
   *
   * Note: This uses O(n) linear scan. For better performance with large caches,
   * consider using a doubly-linked list with Map for O(1) LRU operations.
   * Current implementation is acceptable for default cache size (1000 entries).
   */
  private evictLRUPath(currentTick: number): void {
    let oldestKey: string | null = null;
    let oldestAccess = currentTick;

    for (const [key, entry] of this.pathCache) {
      if (entry.lastAccessed < oldestAccess) {
        oldestAccess = entry.lastAccessed;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      this.pathCache.delete(oldestKey);
      this.lruEvictions++;
    }
  }

  /**
   * Evict the least recently used cost matrix entry
   *
   * Note: This uses O(n) linear scan. For better performance with large caches,
   * consider using a doubly-linked list with Map for O(1) LRU operations.
   * Current implementation is acceptable for default cache size (50 entries).
   */
  private evictLRUCostMatrix(currentTick: number): void {
    let oldestKey: string | null = null;
    let oldestAccess = currentTick;

    for (const [key, entry] of this.costMatrixCache) {
      if (entry.lastAccessed < oldestAccess) {
        oldestAccess = entry.lastAccessed;
        oldestKey = key;
      }
    }

    if (oldestKey) {
      this.costMatrixCache.delete(oldestKey);
      this.lruEvictions++;
    }
  }
}

/**
 * Path serialization utilities for memory-efficient path storage.
 *
 * When storing paths in Memory (e.g., for creep movement), using serialized
 * format significantly reduces memory usage compared to storing RoomPosition objects.
 *
 * Memory savings:
 * - Raw path (5 positions): ~200 bytes
 * - Serialized path: ~30 bytes (85% reduction)
 *
 * @see https://wiki.screepspl.us/Memory/ - Path storage optimization
 * @see https://docs.screeps.com/api/#Room.serializePath
 */

/**
 * Room coordinate bounds (0-49 for both x and y)
 */
const ROOM_MIN_COORD = 0;
const ROOM_MAX_COORD = 49;

/**
 * Memory size estimates for serialization comparison
 * These are approximate sizes based on typical JSON serialization
 */
const BYTES_PER_POSITION_RAW = 40; // RoomPosition JSON: {"x":25,"y":25,"roomName":"W1N1"} ~40 bytes
const BYTES_HEADER_SERIALIZED = 20; // Serialized header: "25,25,W1N1:" ~20 bytes

/**
 * Path step with direction for movement
 */
export interface PathStep {
  x: number;
  y: number;
  dx: number;
  dy: number;
  direction: DirectionConstant;
}

/**
 * Direction constant values (matching Screeps API)
 * These are defined as const values to avoid runtime dependency on global constants
 */
const DIRECTION_VALUES = {
  TOP: 1 as DirectionConstant,
  TOP_RIGHT: 2 as DirectionConstant,
  RIGHT: 3 as DirectionConstant,
  BOTTOM_RIGHT: 4 as DirectionConstant,
  BOTTOM: 5 as DirectionConstant,
  BOTTOM_LEFT: 6 as DirectionConstant,
  LEFT: 7 as DirectionConstant,
  TOP_LEFT: 8 as DirectionConstant
};

/**
 * Direction constants for path encoding
 * Matches Screeps API direction values
 */
const DIRECTION_MAP: Record<DirectionConstant, string> = {
  [DIRECTION_VALUES.TOP]: "1",
  [DIRECTION_VALUES.TOP_RIGHT]: "2",
  [DIRECTION_VALUES.RIGHT]: "3",
  [DIRECTION_VALUES.BOTTOM_RIGHT]: "4",
  [DIRECTION_VALUES.BOTTOM]: "5",
  [DIRECTION_VALUES.BOTTOM_LEFT]: "6",
  [DIRECTION_VALUES.LEFT]: "7",
  [DIRECTION_VALUES.TOP_LEFT]: "8"
};

const REVERSE_DIRECTION_MAP: Record<string, DirectionConstant> = {
  "1": DIRECTION_VALUES.TOP,
  "2": DIRECTION_VALUES.TOP_RIGHT,
  "3": DIRECTION_VALUES.RIGHT,
  "4": DIRECTION_VALUES.BOTTOM_RIGHT,
  "5": DIRECTION_VALUES.BOTTOM,
  "6": DIRECTION_VALUES.BOTTOM_LEFT,
  "7": DIRECTION_VALUES.LEFT,
  "8": DIRECTION_VALUES.TOP_LEFT
};

/**
 * Serialize a path to a compact string format.
 *
 * Format: startX,startY,roomName:d1d2d3...
 * Where d1, d2, etc. are direction digits (1-8)
 *
 * Uses the built-in Room.serializePath() when available in game context,
 * otherwise provides a compatible implementation.
 *
 * @param path Array of RoomPosition objects
 * @returns Serialized path string, or undefined if path is empty
 *
 * @example
 * const path = creep.pos.findPathTo(target);
 * const serialized = serializePath(creep.room.name, path);
 * creep.memory.path = serialized; // Store in creep memory
 */
export function serializePath(roomName: string, path: PathStep[]): string | undefined {
  if (!path || path.length === 0) {
    return undefined;
  }

  // Build direction string
  const directions = path.map(step => DIRECTION_MAP[step.direction]).join("");

  // Store start position and directions
  const start = path[0];
  return `${start.x},${start.y},${roomName}:${directions}`;
}

/**
 * Serialize a RoomPosition array to compact format.
 * Converts RoomPosition[] to PathStep[] format first.
 *
 * @param positions Array of RoomPosition objects
 * @returns Serialized path string, or undefined if path is empty
 */
export function serializePositions(positions: RoomPosition[]): string | undefined {
  if (!positions || positions.length < 2) {
    return undefined;
  }

  const roomName = positions[0].roomName;
  const steps: PathStep[] = [];

  for (let i = 0; i < positions.length - 1; i++) {
    const from = positions[i];
    const to = positions[i + 1];

    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const direction = getDirectionFromDelta(dx, dy);

    if (direction !== undefined) {
      steps.push({
        x: from.x,
        y: from.y,
        dx,
        dy,
        direction
      });
    }
  }

  return serializePath(roomName, steps);
}

/**
 * Deserialize a path string back to RoomPosition array.
 *
 * @param serialized Serialized path string
 * @returns Array of RoomPosition objects, or empty array if invalid
 */
export function deserializePath(serialized: string): RoomPosition[] {
  if (!serialized) {
    return [];
  }

  try {
    const [startPart, directions] = serialized.split(":");
    if (!startPart || !directions) {
      return [];
    }

    const [xStr, yStr, roomName] = startPart.split(",");
    if (!xStr || !yStr || !roomName) {
      return [];
    }

    let x = parseInt(xStr, 10);
    let y = parseInt(yStr, 10);

    if (isNaN(x) || isNaN(y)) {
      return [];
    }

    const positions: RoomPosition[] = [new RoomPosition(x, y, roomName)];

    for (const dirChar of directions) {
      const direction = REVERSE_DIRECTION_MAP[dirChar];
      if (!direction) {
        continue;
      }

      const [dx, dy] = getDeltaFromDirection(direction);
      x += dx;
      y += dy;

      // Ensure we stay within room bounds
      if (x < ROOM_MIN_COORD || x > ROOM_MAX_COORD || y < ROOM_MIN_COORD || y > ROOM_MAX_COORD) {
        break;
      }

      positions.push(new RoomPosition(x, y, roomName));
    }

    return positions;
  } catch {
    return [];
  }
}

/**
 * Get direction constant from dx/dy deltas
 */
function getDirectionFromDelta(dx: number, dy: number): DirectionConstant | undefined {
  // Normalize to -1, 0, or 1
  const ndx = dx === 0 ? 0 : dx > 0 ? 1 : -1;
  const ndy = dy === 0 ? 0 : dy > 0 ? 1 : -1;

  if (ndx === 0 && ndy === -1) return DIRECTION_VALUES.TOP;
  if (ndx === 1 && ndy === -1) return DIRECTION_VALUES.TOP_RIGHT;
  if (ndx === 1 && ndy === 0) return DIRECTION_VALUES.RIGHT;
  if (ndx === 1 && ndy === 1) return DIRECTION_VALUES.BOTTOM_RIGHT;
  if (ndx === 0 && ndy === 1) return DIRECTION_VALUES.BOTTOM;
  if (ndx === -1 && ndy === 1) return DIRECTION_VALUES.BOTTOM_LEFT;
  if (ndx === -1 && ndy === 0) return DIRECTION_VALUES.LEFT;
  if (ndx === -1 && ndy === -1) return DIRECTION_VALUES.TOP_LEFT;

  return undefined;
}

/**
 * Get dx/dy deltas from direction constant
 */
function getDeltaFromDirection(direction: DirectionConstant): [number, number] {
  switch (direction) {
    case DIRECTION_VALUES.TOP:
      return [0, -1];
    case DIRECTION_VALUES.TOP_RIGHT:
      return [1, -1];
    case DIRECTION_VALUES.RIGHT:
      return [1, 0];
    case DIRECTION_VALUES.BOTTOM_RIGHT:
      return [1, 1];
    case DIRECTION_VALUES.BOTTOM:
      return [0, 1];
    case DIRECTION_VALUES.BOTTOM_LEFT:
      return [-1, 1];
    case DIRECTION_VALUES.LEFT:
      return [-1, 0];
    case DIRECTION_VALUES.TOP_LEFT:
      return [-1, -1];
    default:
      return [0, 0];
  }
}

/**
 * Check if a serialized path is still valid for a creep.
 * The path is invalid if:
 * - The creep is not at the start position
 * - The path is empty
 *
 * @param serialized Serialized path string
 * @param currentPos Current position of the creep
 * @returns true if path is valid for the creep's position
 */
export function isPathValid(serialized: string, currentPos: RoomPosition): boolean {
  if (!serialized) {
    return false;
  }

  const positions = deserializePath(serialized);
  if (positions.length === 0) {
    return false;
  }

  // Path is valid if current position matches any position in the path
  return positions.some(
    pos => pos.x === currentPos.x && pos.y === currentPos.y && pos.roomName === currentPos.roomName
  );
}

/**
 * Get remaining steps in a serialized path from the current position.
 *
 * @param serialized Serialized path string
 * @param currentPos Current position of the creep
 * @returns Remaining positions in the path, or empty array if not on path
 */
export function getRemainingPath(serialized: string, currentPos: RoomPosition): RoomPosition[] {
  if (!serialized) {
    return [];
  }

  const positions = deserializePath(serialized);
  const currentIndex = positions.findIndex(
    pos => pos.x === currentPos.x && pos.y === currentPos.y && pos.roomName === currentPos.roomName
  );

  if (currentIndex === -1) {
    return [];
  }

  return positions.slice(currentIndex + 1);
}

/**
 * Calculate memory savings from using serialized paths.
 *
 * @param pathLength Number of positions in the path
 * @returns Object with raw and serialized sizes in bytes (approximate)
 */
export function calculateMemorySavings(pathLength: number): { raw: number; serialized: number; savings: number } {
  const rawSize = pathLength * BYTES_PER_POSITION_RAW;

  // Serialized format: header + one char per step (direction character)
  const serializedSize = BYTES_HEADER_SERIALIZED + Math.max(0, pathLength - 1);

  return {
    raw: rawSize,
    serialized: serializedSize,
    savings: rawSize - serializedSize
  };
}

import { NesCafePathfinder, type NesCafePathfindingOptions } from "./NesCafePathfinder";
import { PathCache, type PathCacheConfig, type PathCacheMetrics } from "./PathCache";

/**
 * Configuration for pathfinding system
 */
export interface PathfindingConfig {
  /** Whether to enable path caching (default: true) */
  enableCaching?: boolean;
  /** Configuration for path cache */
  cacheConfig?: PathCacheConfig;
  /** Logger for debugging */
  logger?: Pick<Console, "log" | "warn">;
}

/**
 * Central manager for pathfinding operations
 * Uses screeps-pathfinding library for advanced traffic management and priority-based movement
 * @see https://github.com/NesCafe62/screeps-pathfinding
 *
 * Key features:
 * - Traffic management (push creeps out of the way or swap with them)
 * - Priority-based movement (higher priority moves execute first)
 * - Move off exit behavior
 * - Terrain and cost matrix caching
 *
 * Usage:
 * 1. Call moveTo() for each creep during your tick
 * 2. Call runMoves() at the end of your tick to execute all scheduled moves
 */
export class PathfindingManager {
  private readonly provider: NesCafePathfinder;
  private readonly logger: Pick<Console, "log" | "warn">;
  private readonly enableCaching: boolean;
  private readonly pathCache: PathCache | null;

  public constructor(config: PathfindingConfig = {}) {
    this.logger = config.logger ?? console;
    this.enableCaching = config.enableCaching ?? true;

    // Initialize path cache if enabled
    this.pathCache = this.enableCaching ? new PathCache(config.cacheConfig) : null;

    // Initialize the NesCafe pathfinding provider
    const cache = this.pathCache ?? new PathCache();
    this.provider = new NesCafePathfinder(cache);

    this.logger.log?.(`PathfindingManager initialized with provider: ${this.provider.getName()}`);
  }

  /**
   * Move a creep to a target using the pathfinding provider
   * Note: For traffic management to work properly, call runMoves() at the end of each tick
   *
   * @param creep - The creep to move
   * @param target - Target position or object with pos property
   * @param opts - Pathfinding options including priority for traffic management
   */
  public moveTo(
    creep: Creep,
    target: RoomPosition | { pos: RoomPosition },
    opts: NesCafePathfindingOptions = {}
  ): ScreepsReturnCode {
    // Apply default reusePath if caching is enabled and not specified
    const options: NesCafePathfindingOptions = {
      ...opts,
      reusePath: this.enableCaching && opts.reusePath === undefined ? 5 : opts.reusePath
    };

    return this.provider.moveTo(creep, target, options);
  }

  /**
   * Find a path from origin to goal
   */
  public findPath(
    origin: RoomPosition,
    goal: RoomPosition | { pos: RoomPosition },
    opts: NesCafePathfindingOptions = {}
  ) {
    return this.provider.findPath(origin, goal, opts);
  }

  /**
   * Run all scheduled moves for the current tick
   * This enables traffic management - higher priority creeps will move first,
   * and lower priority creeps will be pushed out of the way
   *
   * Must be called at the end of each tick after all moveTo() calls
   */
  public runMoves(): void {
    this.provider.runMoves();
  }

  /**
   * Run moves for a specific room only
   * Useful for processing rooms individually
   *
   * @param roomName - The room to process moves for
   */
  public runMovesRoom(roomName: string): void {
    this.provider.runMovesRoom(roomName);
  }

  /**
   * Move creep off road if currently standing on one
   * Useful for creeps that are working and should not block roads
   *
   * @param creep - The creep to move
   * @param options - Movement options
   * @returns true if creep is on road and move was scheduled
   */
  public moveOffRoad(
    creep: Creep,
    options?: {
      target?: RoomPosition;
      range?: number;
      priority?: number;
      moveOffContainer?: boolean;
      moveOffExit?: boolean;
    }
  ): boolean {
    return this.provider.moveOffRoad(creep, options);
  }

  /**
   * Reserve a position for priority-based movement
   * Prevents other creeps from moving to this position
   *
   * @param pos - The position to reserve
   * @param priority - Priority for the reservation
   */
  public reservePos(pos: RoomPosition, priority: number): ScreepsReturnCode {
    return this.provider.reservePos(pos, priority);
  }

  /**
   * Get the direction a creep is planned to move this tick
   *
   * @param creep - The creep to check
   * @returns Direction constant or undefined if no move planned
   */
  public getMoveDirection(creep: Creep): DirectionConstant | undefined {
    return this.provider.getMoveDirection(creep);
  }

  /**
   * Get the serialized path for a creep
   *
   * @param creep - The creep to get path for
   * @returns Serialized path string or undefined
   */
  public getCreepPath(creep: Creep): string | undefined {
    return this.provider.getCreepPath(creep);
  }

  /**
   * Clear the internal cost matrix cache
   * Call when room structures change significantly
   */
  public clearMatrixCache(): void {
    this.provider.clearMatrixCache();
  }

  /**
   * Clear cost matrix cache for a specific room
   *
   * @param roomName - The room to clear cache for
   */
  public clearMatrixCacheRoom(roomName: string): void {
    this.provider.clearMatrixCacheRoom(roomName);
  }

  /**
   * Check if a position is on the room edge (exit tile)
   *
   * @param pos - Position to check
   */
  public isPosExit(pos: { x: number; y: number }): boolean {
    return this.provider.isPosExit(pos);
  }

  /**
   * Get the name of the current pathfinding provider
   */
  public getProviderName(): string {
    return this.provider.getName();
  }

  /**
   * Check if the pathfinding library is available
   * Returns false if screeps-pathfinding failed to load
   */
  public isAvailable(): boolean {
    return this.provider.isAvailable();
  }

  /**
   * Get cache metrics (if caching is enabled)
   * @returns Cache metrics or null if caching is disabled
   */
  public getCacheMetrics(): PathCacheMetrics | null {
    return this.pathCache?.getMetrics() ?? null;
  }

  /**
   * Reset cache metrics
   * Note: Silently does nothing if caching is disabled
   */
  public resetCacheMetrics(): void {
    this.pathCache?.resetMetrics();
  }

  /**
   * Invalidate all cached paths in a specific room
   * Note: Silently does nothing if caching is disabled
   */
  public invalidateRoom(roomName: string): void {
    this.pathCache?.invalidateRoom(roomName);
  }

  /**
   * Invalidate structure-based caches for a room
   * (call this when structures are built/destroyed)
   * Note: Silently does nothing if caching is disabled
   */
  public invalidateStructures(roomName: string): void {
    this.pathCache?.invalidateStructures(roomName);
  }

  /**
   * Clear all caches
   * Note: Silently does nothing if caching is disabled
   */
  public clearCache(): void {
    this.pathCache?.clear();
  }
}

/**
 * Pathfinding options for movement operations
 */
export interface PathfindingOptions {
  /** Target range for pathfinding (default: 1) */
  range?: number;
  /** Number of ticks to reuse a cached path (default: 5) */
  reusePath?: number;
  /** Whether to ignore other creeps when pathfinding (default: false) */
  ignoreCreeps?: boolean;
  /** Maximum number of rooms to search (default: 16) */
  maxRooms?: number;
  /** Maximum operations for pathfinding (default: 2000) */
  maxOps?: number;
  /** Cost matrix callback */
  costCallback?: (roomName: string, costMatrix: CostMatrix) => CostMatrix | void;
  /** Plain terrain cost (default: 1) */
  plainCost?: number;
  /** Swamp terrain cost (default: 5) */
  swampCost?: number;
}

/**
 * Result of a pathfinding operation
 */
export interface PathfindingResult {
  /** The calculated path */
  path: RoomPosition[];
  /** Operations used for pathfinding */
  ops: number;
  /** CPU cost of pathfinding */
  cost: number;
  /** Whether pathfinding was successful */
  incomplete: boolean;
}

/**
 * Abstract interface for pathfinding providers
 * Allows switching between different pathfinding implementations
 */
export interface PathfindingProvider {
  /**
   * Find a path from origin to goal
   */
  findPath(
    origin: RoomPosition,
    goal: RoomPosition | { pos: RoomPosition },
    opts?: PathfindingOptions
  ): PathfindingResult;

  /**
   * Move a creep using this pathfinding provider
   * @returns Movement result code
   */
  moveTo(creep: Creep, target: RoomPosition | { pos: RoomPosition }, opts?: PathfindingOptions): ScreepsReturnCode;

  /**
   * Get provider name for debugging/metrics
   */
  getName(): string;
}

